    fun translate(source: String, language: String): String {
        val index = languages.indexOf(language).takeIf { it >= 0 } ?: 0
        var result = source
        // Longest phrases first to avoid translating a substring before its full phrase.
        phrases.entries.sortedByDescending { it.key.length }.forEach { (ru, values) ->
            result = result.replace(ru, values[index])
        }
        dynamicPrefixes.forEach { (ru, key) ->
            if (result.startsWith(ru)) result = extra[key]?.get(index) + result.removePrefix(ru)
        }
        return result
    }
